+    for (const auto* scale : {&*k_scale, &*v_scale}) {
+      check_cuda_tensor(*scale, "KV scale");
+      check_same_device(qkv, *scale, "KV scale");
+      STD_TORCH_CHECK(
+          scale->numel() == 1 &&
+              scale->scalar_type() == torch::headeronly::ScalarType::Float,
